# coding: utf-8
"""
Elin Italian Localization - loytel.xlsx (Drama Loytel Arc Part 1)
Translates the first 220 entries of Loytel's frontier inspection,
debt notice, 20,000,000 Oren catastrophe, expedition to Vernis,
and discovery of Corgon the dragon child.
"""

import os
import openpyxl

MOD_DIR = os.path.abspath(os.path.join(os.path.dirname(__file__), '..'))
LOYTEL_FILE = os.path.join(MOD_DIR, 'Lang', 'IT', 'Dialog', 'Drama', 'loytel.xlsx')

LOYTEL_PART1 = {
    8: "Che c'è? Fa' in fretta, ho un mucchio di lavoro da sbrigare.",
    10: "Avrei delle domande da farti.",
    11: "Potresti darmi qualche consiglio sullo sviluppo dell'insediamento?",
    16: "Cosa desideri sapere?",
    17: "Sul lavoro di Ash e Fia",
    18: "(Indietro)",
    22: "Non ti hanno spiegato nulla? Beh, allora forse è meglio per la tua incolumità che tu rimanga all'oscuro.",
    25: "Ottima attitudine. Di cosa vuoi che ti parli?",
    26: "Sulla Pietra del Focolare",
    27: "Sul Prestigio della Dimora (Home Ranking)",
    28: "Sull'apertura di un'attività commerciale",
    29: "Sulla gestione di un'attrazione turistica",
    30: "Sulla gestione di una bottega",
    31: "Sulle Terre Esenti da Imposte",
    32: "(Indietro)",
    36: "Tra tutti i mobili collocati nella tua dimora, i più preziosi vengono designati come 'Cimeli di Famiglia'. La competizione basata sul valore di questi cimeli è nota come 'Classifica delle Dimore'.\n\nSe riesci a posizionarti tra le prime 125 dimore della classifica, riceverai una cospicua rendita mensile, che si rivelerà una fonte di introiti inestimabile nelle fasi iniziali!\n\nPuoi verificare i cimeli attualmente registrati, la tua posizione in classifica e i relativi premi direttamente dalla Bacheca della Dimora.",
    40: "Che tu voglia allestire un'attrazione turistica o aprire una bottega, è ovvio che senza avventori non si fa alcun affare! Per attirare visitatori nella tua dimora, devi promulgare l'editto 'Apertura al Pubblico'.\n\nQuando questo editto è in vigore, inizieranno ad affluire clienti in base alla notorietà della tua terra. La maggior parte vi pernotterà per qualche giorno: fornendo loro dei comodi letti, potrai riscuotere anche le tariffe di soggiorno!\n\nHo copie del tomo dell'editto in vendita nella mia mercanzia: dacci un'occhiata se intendi acquistarlo.",
    44: "La tua dimora possiede un valore turistico intrinseco, che cresce esponenzialmente esponendo statue, figurine, carte da collezione e dipinti di pregio.\n\nQuando il valore turistico è elevato, incasserai proventi turistici giornalieri dai viandanti di passaggio. All'inizio, con pochi pezzi in mostra, gli incassi saranno modesti, ma sul lungo periodo costituiscono un flusso costante di entrate.",
    48: "Ti piacerebbe metterti a capo di una bottega?\n\nPuoi vendere merci agli avventori applicando cartellini del prezzo agli articoli esposti nella tua dimora. Rispetto alla cassa di spedizione richiede un pizzico di tempo in più, ma garantisce profitti di gran lunga superiori!\n\nPuoi fabbricare facilmente i cartellini del prezzo presso il Laboratorio dei Cartelli: fai una prova se l'idea ti stuzzica!",
    49: "Oh, e già che ti trovi al laboratorio, dovresti fabbricare anche il 'Cartello di Rifornimento Merci'.\n\nQuando un articolo viene venduto, compare automaticamente un cartellino di 'esaurito' al suo posto. Se nei dintorni del cartello vi sono altri oggetti della medesima categoria, i residenti provvederanno a rifornire gli scaffali al posto tuo!",
    50: "Lascia che ti sveli una dritta magistrale:\nse applichi un cartellino del prezzo a un baule contenente merci, potrai vendere l'intero contenuto in un unico blocco!\n\nUna volta venduto tutto, il cartellino si staccherà automaticamente. Se trovi noioso riattaccarlo ogni volta, ti basterà lasciare all'interno un singolo 'oggetto non vendibile' come segnaposto!",
    54: "Sulla tua terra svetta una pietra mistica nota come 'Pietra del Focolare': uno spirito pietrificato che, in virtù di antichi patti, assicura la prosperità dell'insediamento.\n\nLa crescita della Pietra del Focolare è cruciale: incrementa il potere amministrativo necessario per promulgare editti, sblocca modalità avanzate di costruzione e impedisce ai nemici di distruggere i manufatti della base!",
    55: "Per far progredire la pietra devi accumulare la sua esperienza fino al massimo consentito. I punti crescono col trascorrere del tempo anche se non fai nulla, ma possono essere accelerati grandemente spedendo merci o tramite specifiche mansioni svolte dai coloni.\n\nSpedendo regolarmente merci superflue e reclutando molti braccianti, l'esperienza salirà spontaneamente.\n\nUna volta colma la barra, la pietra salirà automaticamente al grado successivo!",
    56: "Un dettaglio vitale da rammentare: man mano che la Pietra del Focolare cresce, aumenterà anche la ferocia dei nemici che assalteranno la tua terra! Se ti accorgi che gli aggressori attuali ti mettono in seria difficoltà, promulga l'editto di 'Soppressione della Crescita' per prender tempo.",
    60: "Non vi è alcuno svantaggio nel possedere molte terre, ma accumulare appezzamenti alla cieca non raddoppierà magicamente le tue entrate.\n\nA Mysilia vige uno speciale regime di sgravio fiscale, e questo privilegio viene applicato automaticamente ai primi appezzamenti che acquisisci.\n\nPer ora non devi crucciartene, ma tieni a mente che trarre lauti profitti da terre prive di esenzione fiscale è un'impresa ardua.",
    61: "Al momento solo tre tenute possono godere dello status di terre esenti da imposte. Se hai intenzione di sviluppare mete turistiche o locande, tienilo bene a mente!\n\nLe tasse sulle terre non esenti colpiscono i proventi turistici, gli affitti delle stanze e le imposte di soggiorno. Le spedizioni e le vendite dirette di merci non subiscono tassazione, quindi puoi procedere senza timori.",
    65: "Perché quella cera funerea? Non c'è motivo di avvilirsi!\n\nCerto, sento che le lusinghe di Ashland mi hanno un po' raggirato, ma lavorare in tutta tranquillità immersi nella natura incontaminata non è poi così male. Per un ispettore del mio calibro le commesse dai nobili più blasonati di Mysilia fioccano a fiumi: forse la mia povera anima affaticata aveva proprio bisogno di una tregua rilassante in mezzo a questi prati!",
    66: "Stai pure sereno: al momento mi sento quasi riconoscente verso Ashland. Svolgerò i miei doveri con scrupolosa dedizione, e con me al timone l'avvenire di questa terra è praticamente cosa fatta!",
    67: "Ora, avrai certamente mille progetti in testa, ma prima di ogni altra cosa dobbiamo rimpinguare le casse!\n\nFondi copiosi sono la linfa vitale di ogni nuova colonia. Bagni caldi, materassi soffici e l'aroma di vini liquorosi non fanno al caso tuo per ora! Prima dobbiamo arricchire la colonia fin dalle radici.\n\nIl mezzo più sbrigativo per fare quattrini è spedire beni tramite la cassa di spedizione. Una volta dissodati i campi e raccolto il grano, avremo un flusso costante e sicuro.",
    68: "...Uhm, cos'è quello sguardo vacuo? Non dirmi che non hai mai sentito nominare una cassa di spedizione in vita tua?!",
    69: "...",
    70: "Incredibile... Non mi dirai che non c'è ancora una cassa di spedizione su questa terra?! Ma dove siamo finiti, all'età della pietra?!\n\n...Tieni, ti fornirò io i materiali necessari per fabbricarne una. Costruisci una 'cassa di spedizione' dal 'banco da lavoro' e piazzala a terra.",
    74: "...E bada bene a usare il legname di palulu che ti ho appena consegnato! La cassa di spedizione deve sfoggiare la tonalità chic ed elegante tipica del legno di palulu: non tollererò alcun surrogato, urterebbe il mio raffinato senso estetico!\n\nNel caso non lo sapessi, puoi cliccare sull'icona dell'ingrediente nella schermata di creazione per cambiare il materiale impiegato.",
    80: "Uhm, un colore sobrio e rassicurante: davvero un'ottima cassa di spedizione! Finalmente un primo raggio di civiltà risplende su questa landa selvaggia!\n\nLe merci riposte nella cassa vengono prelevate automaticamente ogni mattina all'alba, e il ricavato ti verrà recapitato all'istante. Se spedisci un volume consistente di beni, ti verranno corrisposti persino lingotti d'oro!\n\nOra mi è venuto un cerchio alla testa e vado a riposare, ma tu approfittane per gettare un po' di merci nella cassa.",
    89: "Ma come diavolo ti sei conciato?! ...Prendi forse sottogamba il nobile mestiere della colonizzazione?",
    90: "Non sono solito rimproverare i pionieri seri, ma disprezzo con tutto me stesso coloro che trattano l'avventura come un passatempo frivolo o una fantasia da perdigiorno! Chi non dimostra fermo impegno può fare le valigie e andarsene seduta stante, senza discussioni!",
    91: "Dunque, stavo per impartirti i sacri rudimenti dell'agricoltura, ma vestito come un pezzente seminudo sei del tutto inadeguato ai campi! Il tuo contegno ha sollevato pesanti dubbi nella mia mente, perciò prima intendo saggiare la tua tempra di pioniere!\n\nFabbricati con le tue sole forze una 'Zappa' e una 'Vanga'. Quando avrai assemblato entrambi gli attrezzi, torna a fare rapporto.",
    97: "Uhm, eccellente lavoro! Sono davvero una 'Zappa' e una 'Vanga' di pregevole fattura. Ti donano parecchio!\n\nCon la vanga puoi estirpare le erbacce, dopodiché dissoda la terra con la zappa per creare un campo coltivabile, indispensabile per seminare. Come ricompensa ti dono queste sementi: allestisci un campo e interrale con cura.",
    98: "Prima che tu vada, lascia che ti insegni una nozione capitale:\nogni singola pianta su questa terra consuma la 'fertilità' del suolo. Se la fertilità crolla, la terra inaridirà e il rendimento dei tuoi raccolti colerà a picco!\n\nPuoi verificare la fertilità attuale sulla bacheca della dimora. Quando scarseggia, la contromisura più rapida consiste nel falciare le erbacce e abbattere gli alberi incolti nei dintorni. Ricordatelo bene!",
    106: "...",
    107: "...",
    108: "Cos'è quell'aria tetra e compunta che avete addosso tutti e due?\n\nAccumulare angosce nuoce alla salute! Perché non prendete esempio da me, e non vi godete la serena maestosità di questi prati?",
    109: "Ah, Loytel, arrivi a fagiolo. In verità mi è appena stata recapitata questa missiva da Mysilia...",
    110: "...Una lettera, dici? Vediamo un po' cosa c'è scritto.",
    112: "\"Carissimo Loytel,\n\nCon sommo rammarico ti informiamo che la collezione di fiori rari da te appassionatamente raccolta — in particolar modo il 'Fantomatico Tulipano Azzurro' — è stata periziata come un falso grossolano. I cospicui fondi da te investiti sono irrecuperabili; inoltre, è emerso che la coltivazione di tale specie è severamente bandita a Mysilia. Poiché il fiore è stato esibito dalla famiglia reale durante la Giornata Commemorativa del Principato, sei formalmente incriminato per gravissimo oltraggio all'onore della corona, con conseguente addebito di un debito di venti milioni di oren.\n\nLa congiuntura è oltremodo ardua, stimato signore, ma confidiamo che saprete superare quest'avversità e riconquistare l'antico lustro.\n\nCon deferenza,\nL'Ufficio delle Finanze di Mysilia\"",
    113: "...",
    114: "Dunque... questo significa che sono sul lastrico e gravato da un debito titanico di venti milioni di oren?!",
    115: "...Sì, a quanto pare proprio così.",
    116: "Mi piacerebbe proprio posare gli occhi su quel falso tulipano, una volta rientrati a Mysilia...",
    117: "(prende un profondissimo respiro)",
    118: "...Ecco qual è la situazione. Hai compreso la gravità, #pc?\n\nÈ una fortuna sfacciata che mi trovassi quassù in questo prato quando si è abbattuta questa tragedia assurda! Fossi stato a Mysilia, sarei già marcito in galera per un misfatto che non ho commesso!",
    119: "...Ebbene, trasformeremo questa terra in una sfolgorante metropoli traboccante d'oro e ripagheremo fino all'ultimo centesimo, costi quel che costi! Niente panico: con il mio acume e la mia saggezza, supererò anche questa tempesta!",
    120: "Un fantomatico tulipano azzurro... Sentendolo nominare, non ti è parso un tantino sospetto fin dal primo istante?",
    121: "...Mi pulsa violentemente la testa: ho bisogno di riposare.",
    122: "...",
    123: "Venti milioni di oren... È una somma con cui si comprerebbe a occhi chiusi un'intera cittadina.",
    124: "Conoscendo Loytel, troverà senz'altro il modo di sbrogliare la matassa... probabilmente.",
    134: "Messer Loytel, sono ore che fissate il firmamento con aria assorta...",
    135: "Ah, milady Farris. Nulla di che... stavo solo ripensando ai bei vecchi tempi trascorsi alla corte di Mysilia.\n\nLa vita in questa sterminata pianura non mi dispiace affatto, ma mi domando se verrà mai il giorno in cui potrò sorseggiare di nuovo il prelibato nettare di Olvina...",
    136: "...In realtà siete in ansia per il debito, non è vero?",
    137: "...Mentirei spudoratamente se dicessi che non mi toglie il sonno. Ma, dopotutto, porto con fierezza il titolo di ispettore della frontiera di Mysilia! Devo gettarmi alle spalle questa sciagura e consacrarmi anima e corpo allo sviluppo di queste terre.",
    138: "Le vostre parole sono un balsamo per il cuore, messer Loytel. Ma mi chiedo: il fallimento è davvero un'oscurità da fuggire a ogni costo? E la sventura è sempre un'ombra da schivare?",
    139: "...",
    140: "Non me ne intendo molto di dissodamenti e pionieri, eppure a volte le cose più sublimi sono le opere d'arte nate proprio dagli sbagli! Messer Loytel, io credo fermamente che saprete forgiare la vostra forza da questa sventura e reclamare la gloria perduta!",
    141: "Che intuizione sfolgorante... Milady Farris, le vostre parole mi commuovono nel profondo!",
    142: "Sì, colonizzare è un'arte! Non si tratta di cancellare le disgrazie, ma di usarle come concime per plasmare un futuro radioso! Ho imparato una lezione impagabile dalla vostra saggezza.\n\nA differenza di Ash e Fiama, voi siete una donna di straordinaria levatura intellettuale! Milady Farris, vi prego di continuare a offrirmi il vostro sostegno!",
    143: "Ma con tutto il cuore! Anzi, stavo giusto componendo una nuova ballata per infondervi coraggio, intitolata 'Danza di Sogni nell'Illusione Azzurra'!",
    144: "(trattiene il fiato)",
    145: "È stato un vero peccato che i tulipani azzurri fossero contraffatti, ma l'ispirazione poetica che la vostra tragedia ci ha donato è autentica come l'oro! Per questo desidero tramutare la vicenda dei tulipani azzurri in una canzone da cantare ai coloni che verranno! Chiunque la ascolterà visualizzerà l'effimera bellezza di quei fiori perduti, e rimarrà scosso dalla vostra abnegazione per la frontiera!",
    146: "Milady Farris... voglio dire, ecco...",
    147: "Che avete, messer Loytel?",
    148: "È solo che... mi è tornato un fortissimo cerchio alla testa... Sono certissimo che sia un capolavoro sublime, ma vi prego, concedetemi del tempo per riflettere...",
    158: "Messer Loytel, milord #pc, arrivate al momento giusto! Quei due viandanti laggiù desiderano conferire con voi.",
    159: "Uhm, viandanti, dite? A vederli sembrano innocui, benché abbiano un abbigliamento decisamente singolare.",
    160: "Mi hanno riferito di essere alchimisti erranti: a quanto pare vagano esplorando terre remote.",
    161: "Alchimisti, sentite un po'... Ostentando un titolo tanto ambiguo, cercheranno sicuramente di propinarci intrugli e pozioni scadenti! L'alchimia poi, figuriamoci se...\n\nUn momento, fermi tutti... Quella placca di piombo che quell'uomo porta al collo non mi è affatto nuova!",
    162: "Quel riflesso opaco su piombo verdastro, inciso con l'emblema solare... Non v'è dubbio alcuno: è il sigillo di massimo merito dell'Accademia Reale di Palmia, concesso unicamente a chi ha primeggiato con lode accademica assoluta! Chi sfoggia quella placca verrebbe accolto con tutti gli onori in qualunque corte regale di Tyris!\n\n...Stento a crederci, ma quell'individuo dall'aria scanzonata è l'élite dell'élite!",
    163: "Coff coff... Hai compreso, #pc?\n\nQuesto viaggiatore dev'essere un illustre maestro alchimista di chiara fama! Bada bene a tenere a freno la lingua e comportati con la massima riverenza!",
    164: "...",
    165: "Benvenuti tra noi, nobili viaggiatori!\n\nBenché questa non sia che una vasta distesa erbosa, vi è forse qualcosa che possiamo fare per voi?",
    166: "Felicissima giornata a voi, pionieri di questa terra! Definire questa distesa un vuoto desolato tradisce la verità: qui spira la brezza della libertà, e ferve la speranza!\n\nVi siamo immensamente grati per la calorosa accoglienza. Il mio nome è Kettle, e costei è la mia compagna di viaggio, Quruitzia.",
    167: "...",
    168: "Abbiamo udito del vostro insediamento durante le nostre peregrinazioni, e speravamo di trovare un tetto e un tozzo di pane per la notte. Non saremo d'intralcio, mi auguro?",
    169: "Ma niente affatto, mastro Kettle! Io sono Loytel, l'ispettore di frontiera incaricato di queste terre. Siete i benvenuti a riposare le vostre stanche membra qui finché lo desiderate!",
    170: "Siete oltremodo cortese. In questo luogo si respira una singolare armonia, e posso percepire il fluire puro del mana: durante i nostri viaggi ci è capitato assai di rado di scorgere simili oasi. Speravo proprio di poter perlustrare i dintorni con calma.",
    171: "Davvero affascinante. Ora che ci penso, Ash accennò a qualcosa di simile tempo fa. Le sue intuizioni sono un terno al lotto, ma se lo confermate anche voi, forse questa terra cela davvero qualcosa di prodigioso!",
    172: "In ogni caso, avere al nostro fianco un alchimista del vostro rango è una rassicurazione inestimabile!\n\nPermettetemi di rinnovarvi il mio più caloroso benvenuto, mastro Kettle: spero con tutto il cuore che il vostro soggiorno qui si riveli fecondo per entrambi!",
    182: "Oh, già all'opera ai fornelli? Ammirevole solerzia di buon'ora, Quru... Quru...",
    183: "Quruitzia.",
    184: "Giusto, Quruitzia! Volevo domandarti: come mai mastro Kettle tiene costantemente gli occhi serrati?",
    185: "...",
    186: "...",
    187: "È non vedente.",
    188: "C-capisco... Ti chiedo umilmente perdono, è stata una domanda del tutto priva di tatto da parte mia... Ma la cecità non gli rende oltremodo ardua l'alchimia? Senza contare che viaggiare per il mondo deve essere una sfida proibitiva!",
    189: "...",
    190: "...",
    191: "Ci sono io con lui.",
    192: "G-giusto, ma certo! Con una compagna affidabile e risoluta come te al suo fianco, deve sentirsi infinitamente sollevato! È come se foste uniti da invisibili e saldi fili di devozione!",
    193: "...",
    194: "...",
    195: "Fa... fa un freddo pungente oggi, non trovi?\n\nA proposito, che delizia è mai questa pietanza? Emana un profumo delizioso che mi ha incuriosito fin da prima!",
    196: "È stufato di noci Api... Se volete, prendetene un piatto.",
    197: "Oh, le noci Api sono la mia passione assoluta! E per giunta in uno stufato fumante appena tolto dal fuoco! Ma sì, lasciami assaggiare una cucchiaiata!",
    198: "...",
    199: "...Cough, ack, gulp!",
    200: "...",
    201: "Questo è... uno stufato decisamente... singolare! Voglio dire, è... un approccio audace e innovativo che mi ha colto di sorpresa! Il sentore delle noci Api regala... una consistenza inedita, ecco...",
    202: "Muori!",
    203: "Ma... Ehi, Quruitzia, dove stai correndo?! Aspetta! Quruitzia!",
    204: "...",
    205: "Fiuuu... Che fanciulla suscettibile e lunatica. La vedo davvero dura...",
    216: "Mastro Kettle, potrei rubarvi qualche istante del vostro prezioso tempo?",
    217: "Chiamami pure solo Kettle. Di cosa hai bisogno?",
    218: "Ebbene, Kettle, desideravo chiederti una cosa da un po'.\n\nL'alchimia è prodigiosa per distillare pozioni, panacee e unguenti rari. Ma alla sua radice, è lo studio deputato a trasmutare metalli vili in metalli preziosi, non è così?... No, non giriamoci intorno: puoi tramutare le cose in oro massiccio?",
    219: "Ah, l'oro...\n\nPurtroppo questo travalica le mie attuali facoltà. Per trasmutare della volgare ferraglia in oro zecchino occorrerebbe la leggendaria 'Pietra Filosofale', una gemma magica di cui parlano le ballate antiche ma che nessun vivente ha mai potuto contemplare.",
    220: "...Lo immaginavo. Non vi sono scorciatoie facili a questo mondo...",
    221: "...",
    222: "Non posso trasmutare l'oro. Ma se ciò che brama il tuo cuore è l'oro, vi sono sentieri assai più diretti per entrarne in possesso.",
    223: "...",
    224: "Ti prego, prosegui... sono tutt'orecchi!",
    225: "Molto a nord da qui, ai piedi di un'aspra catena montuosa, sorge una collina nota col nome di Vernis. Nelle sue cavità sotterranee riposa una ricchissima vena mineraria, un tempo sfruttata come miniera di carbone. Tuttavia, quando orde di mostri presero a infestarla, i cunicoli vennero abbandonati e ora nessuno osa più avventurarvisi.",
    226: "...Le dimenticate miniere di Vernis custodiscono ancora giacimenti auriferi. Naturalmente, reclamarli esige un ardimento — o un'incoscienza — pari all'abbagliante fulgore del metallo.",
    227: "Che rivelazione straordinaria, Kettle! Ci hai appena fornito un'informazione dal valore incalcolabile!",
    228: "L'oro dimenticato nelle viscere di Vernis... hai inteso, #pc? Pare proprio che zappare queste zolle infestate da erbacce e sassi non sia più la nostra massima priorità! Dobbiamo fare rotta verso Vernis e dissotterrare quel tesoro!",
    229: "Vorrei partire seduta stante, ma immagino che tu debba allestire i tuoi preparativi. Parla con me quando ti sentirai pronto a inaugurare la spedizione a Vernis!",
    239: "Kettle riferisce che Vernis si trova procedendo dritto verso nord da qui. È una marcia impegnativa, perciò è saggia precauzione stipare nello zaino provviste a sufficienza per l'andata e il ritorno.",
    240: "Poiché potremmo trattenerci lassù per diverso tempo, assicurati di sbrigare ogni faccenda in sospeso in questa base.\n\nIo mi muoverò in avanscoperta per perlustrare la zona: vieni a cercarmi non appena metti piede a Vernis!",
    244: "Ah, #pc, sei finalmente giunto a destinazione!",
    245: "Dunque è questa Vernis, un tempo fiorente borgo minerario...\n\nDai racconti di Kettle mi ero illuso che i cunicoli fossero stati dismessi di recente, e invece pare che siano abbandonati da interi decenni! Ho fatto una ricognizione nei dintorni e non ho rinvenuto altro che macerie e ragnatele.",
    246: "...",
    247: "Tu... hai appena fatto una smorfia decisamente poco entusiasta, non è vero?",
    248: "...",
    249: "...#pc, contemplando queste miniere in rovina e questa terra desolata, non avverti assolutamente nulla nel profondo del tuo animo?",
    250: "Un tempo questo luogo brulicava di vita e speranza incise su ogni singolo ciottolo. Purtroppo la luce si è affievolita con gli anni, e oggi non ne sopravvive neppure l'ombra.",
    251: "...Eppure io riesco a udirle! Le voci di questi ciottoli corrosi e di questa terra esausta che sussurrano i fasti di un tempo!\n\n\"Messer #pc, Vernis non è ancora spacciata...\"\n\"Messer #pc, possiamo ancora farcela...\"\n\"Messer #pc, non abbandonateci al nostro destino...!\"",
    252: "Le odi anche tu, non è vero?\n\nVernis non è una tomba dimenticata: è una culla di infinite possibilità, l'inizio di una nuova era! Desidero con tutto me stesso vedere il giorno in cui questi vicoli risuoneranno ancora delle risate della gente!",
    257: "Questo terreno è troppo dissestato per attirare nuovi coloni. Persino l'imbocco della miniera è ostruito da macigni colossali!\n\nPrima di inaugurare la colonizzazione vera e propria, dobbiamo bonificare l'area.",
    258: "Forse riusciresti a frantumare quei colossi di roccia con un piccone rinforzato, ma sarebbe una fatica titanica!\n\nLascia che ti insegni come fabbricare un ordigno: è la formula di una bomba artigianale chiamata 'Flam'. Fabbricane qualcuna e fai saltare in aria tutte le rocce che sbarrano il cammino!",
    260: "Per nostra fortuna Vernis era una cittadina mineraria: i materiali necessari per la polvere esplosiva dovrebbero trovarsi facilmente nei paraggi!\n\nBada che il potere distruttivo dell'ordigno dipende dalla durezza della roccia impiegata: un flam a base di granito sarà più che sufficiente per ora.\n\nQuando avrai polverizzato tutti i macigni, torna a fare rapporto.",
    266: "Oh, hai già finito di bonificare?\n\nOra non ci resta che rivendicare i diritti legali sulla terra e daremo il via ai lavori! Ti consegno l'atto di proprietà: leggilo a voce alta!",
    267: "Ma prima di farlo, permettimi di metterti a parte di qualche avvertenza capitale sull'acquisizione di nuove concessioni.",
    268: "Puoi possedere tutti i possedimenti che desideri, ma quando intoni una Pergamena del Ritorno verrai ricondotto unicamente alla tua dimora principale. Puoi cambiare la dimora principale interagendo con la Pietra del Focolare, perciò controlla bene quando annetti una nuova terra.",
    269: "Se desideri trasferire coloni dalla vecchia base, invitali nel tuo gruppo e scortali nella nuova dimora prima di assegnarli. Tuttavia, è assai più pratico spostarli nella Pietra del Focolare tramite la bacheca dei residenti e rievocarli sul posto!",
    270: "Per adesso questo è quanto.\n\nNon c'è alcun malus nel gestire molteplici possedimenti, e man mano che le basi crescono sbloccherai prodotti d'eccellenza e viaggi rapidi tra le colonie! Perciò continua ad ampliare i nostri confini!",
    279: "Bene! Ora possiamo sviluppare Vernis senza alcun freno!\n\nAl momento è solo un cumulo di macerie, ma non appena innalzeremo le prime baracche i minatori accorreranno a frotte! Con la capitale reale Palmia a oriente e il porto di Kapul a occidente, la posizione strategica è a dir poco promettente!",
    280: "Vedo con piacere che i lavori procedono a gonfie vele.",
    281: "Ah, Kettle, sei arrivato! E c'è anche Quruitzia!",
    282: "...",
    283: "Ci servirà ogni braccio disponibile su questa nuova frontiera, perciò li ho convocati entrambi. Ora siamo davvero pronti a tutto!",
    284: "A proposito, ti sei già addentrato nei cunicoli? Sono dovuto tornare indietro per via di mostri che pattugliavano l'ingresso, ma sembra che vi siano ancora filoni ricchissimi intatti. Quando hai tempo, esplora le gallerie!",
    285: "Sebbene l'oro sopito nella miniera mi tolga il sonno, per ora la colonizzazione resta la nostra priorità assoluta. Potremo spingerci più in profondità quando arriveranno nuovi minatori.\n\nFai prosperare questa terra e potenzia la Pietra del Focolare, poi torna a fare rapporto!",
    286: "Ebbene, cosa stiamo aspettando? Facciamo rinascere Vernis e restituiamole i suoi fasti di operosa città mineraria!",
    294: "(un ruggito tonante rimbomba dal sottosuolo) ROOOOOAAAARGH!!",
    295: "...",
    296: "Ancora quella voce tremenda! Sta terrorizzando i minatori a tal punto che molti stanno fuggendo a gambe levate! Pare provenire dalle viscere della terra... cosa diavolo sta succedendo laggiù?!",
    297: "Messer Loytel, riguardo a questa faccenda...\n\nCircolano voci insistenti su un'ombra titanica avvistata nelle profondità delle gallerie. Si dice che l'ombra abbia scandito queste parole:\n\n\"IO SONO IL DRAGO D'ACCIAIO CORGON. OFFRITE LA FANCIULLA DAI CAPELLI ROSSI COME SACRIFICIO. ANDATEVENE, SE CARA VI È LA VOSTRA MISERA VITA!\"",
    298: "...",
    299: "Questa suona proprio come un'estorsione... sebbene un po' sconclusionata... Quel nome, il Drago d'Acciaio Corgon, non mi è nuovo.",
    300: "Un tempo a Palmia esistevano tre pietre magiche custodi di un potere incommensurabile. Furono affidate agli esseri più formidabili e temibili come chiavi per suggellare un arcano.\n\nUna di queste, la Pietra Magica del Saggio, fu donata al leggendario drago, Corgon il Drago d'Acciaio. Benché si dicesse che fosse stato abbattuto vent'anni fa dall'uccisore di draghi Thorran.",
    301: "Un drago che dovrebbe essere defunto da tempo... La faccenda si fa oltremodo spinosa! E poi mi insospettisce quella pretesa di 'sacrificare la fanciulla dai capelli rossi'... Una ragazza dalla chioma scarlatta, chi mai potrebbe...?",
    302: "...",
    303: "...",
    304: "Se dovessimo sacrificare Quruitzia...",
    305: "...Messer Loytel!",
    306: "N-no, stavo solo speculando sull'assurdità della richiesta! Com'è ovvio, non piegheremo mai il capo a simile ricatto!\n\nEppure... un drago rintanato nei meandri della miniera, eh?",
    307: "Oro. Si narra che il Drago d'Acciaio sia ghiotto d'oro.",
    308: "Capisco: la proverbiale cupidigia dei draghi per i tesori! Dunque stai suggerendo che nei meandri della miniera giaccia nascosto un tesoro inestimabile accumulato dalla bestia!",
    309: "No, la leggenda narra che il Drago d'Acciaio l'oro se lo mangi per davvero.",
    310: "...",
    311: "...Beh, questo semplifica notevolmente la questione!",
    312: "Hai inteso, #pc? Ora tocca a te! Non possiamo permettere a un drago sfacciato che banchetta col nostro oro di bivaccare a Vernis un minuto di più!\n\nVorrei sguinzagliarti all'istante, ma dovrai pur prepararti a dovere. Rivolgiti a me non appena sarai pronto a dare la caccia al drago!",
    318: "Affrontare un drago esige una preparazione impeccabile. Corazze di fattura sublime sono d'obbligo, e dovrai premunirti contro il suo alito infuocato aumentando la resistenza al fuoco e proteggendo i tuoi beni dall'incendio!",
    319: "Ne saprai sicuramente più tu di me essendo un avventuriero, ma lascia che ti rinfreschi la memoria:\nle resistenze elementali riducono grandemente i danni di quell'elemento e abbattono la probabilità di subire ustioni o cecità!\nInoltre, se vieni investito da fiamme o gelo, i tuoi averi potrebbero incenerirsi o andare in frantumi: infila nello zaino coperte ignifughe e coibentate per scongiurare disastri!",
    321: "Tieni, prendi questi intrugli: ho chiesto a Kettle di distillare alcuni preparati che ti saranno di vitale aiuto nella caccia al drago.\n\nIl mostro ha fatto il suo nido nei recessi più profondi: prendi anche questa chiave per i livelli inferiori!",
    322: "Magnifico, ora sei equipaggiato di tutto punto!\n\nScendi con cautela nei livelli inferiori e valuta accuratamente le tue forze. Se i mostri dovessero rivelarsi troppo soverchianti, non esitare a ripiegare e riorganizzarti!",
    330: "Che cos'è questa sinistra aura di morte che grava nell'aria...?\n\nSì, #pc, eravamo in pensiero per te e abbiamo deciso di seguirti!",
    331: "Guardate quanti orrendi cadaveri carbonizzati giacciono sparsi ovunque... È opera del Drago d'Acciaio?",
    332: "No, i draghi non agiscono in questo modo.\n\nI draghi sono creature singolari: il destino si plasma attorno alla loro possanza, attirando esseri ammaliati da quel potere.\nQuesto corpo incenerito emana un lezzo inconfondibile... appartiene a Tephra, l'antico demone della roccia ardente, maestro delle fiamme divoratrici.",
    333: "Un demone... dev'essere il tirapiedi di Corgon! Bene, #pc, questo è pane per i tuoi denti!\n\n...È un compito da avventurieri, com'è ovvio! Ti aspetterai mica che un Ispettore di Frontiera si metta a duellare con simili obbrobri?!",
    336: "Eccolo che arriva! Mostra a quel demone di che pasta sei fatto!",
    344: "Ce l'hai fatta!\n\nChe tempra formidabile! Devo riconoscerlo, mi hai davvero impressionato!\n\nTuttavia, ora che il suo servitore è caduto, il Drago d'Acciaio non se ne starà con le mani in mano... Ma che... cos'è quell'ombra colossale...?!",
    350: "IO SONO IL DRAGO D'ACCIAIO CORGON.\n\nSTUPIDI ESSERI UMANI.\n\nANDATEVENE, SE CARA VI È LA VOSTRA MISERA VITA!",
    351: "Parli del diavolo ed eccolo che spunta dalle tenebre! Sei pronto, #pc?!",
    352: "IO SONO IL DRAGO D'ACCIAIO CORGON...\n\nSTUPIDI ESSERI UMANI...\n\nANDATEVENE, SE CARA VI È LA VOSTRA MISERA VITA...",
    353: "Ugh, che voce cavernosa e terrificante! Sta arrivando, #pc, tieni gli occhi aperti!",
    354: "IO SONO IL DRAGO D'ACCIAIO CORGON...\n\nANDATEVENE, SE CARA VI È LA VOSTRA MISERA VITA...",
    355: "...",
    356: "IO SONO IL DRAGO D'ACCIAIO CORGON...",
    357: "C'è... qualcosa che non quadra, non trovate?",
    358: "...",
    359: "IO SONO IL DRAGO D'ACCIAIO CORGON...!\n\nANDATEVENE, SE CARA VI È LA VOSTRA MISERA VITA...!\n\nIO SONO IL DRAGO D'ACCIAIO CORGON...!\n\nANDATEVENE, SE CARA VI È LA VOSTRA MISERA VITA...!",
    360: "Uhm... questo drago continua a ripetere le medesime parole a macchinetta come un ingranaggio rotto! La faccenda puzza sempre di più!",
    361: "#pc, prestami la tua torcia: facciamo un po' di luce là dentro... Avanti, mostrati alla luce, Drago d'Acciaio Corgon!",
    366: "(...mokyuu...)",
    367: "...",
    368: "...",
    369: "Ma che razza di sgorbio sarebbe questo...?!",
    370: "Non mi dire che... era questo coso a proiettare un'ombra tanto mostruosa...?!",
    371: "È un... cucciolo di drago...",
    372: "Questo cosetto potrei stenderlo pure io con un ceffone! E sarebbe questa creaturina ad aver terrorizzato i minatori usurpando il nome del Drago d'Acciaio?!",
    373: "...Un piccolo drago... e il Drago d'Acciaio Corgon, ritenuto estinto da decenni... Comprendo: questo piccoletto dev'essere l'ultimo discendente superstite di Corgon.",
    375: "Il figlio di Corgon...",
    378: "Sì, deve aver ripetuto a memoria quelle parole imitando il genitore.\n\n...O forse, il morente Corgon in persona gliele insegnò in punto di morte affinché gli umani non osassero accostarsi al cucciolo...",
    379: "(mokyu...)",
    380: "...",
    381: "(bisbigliando) ...Messer Loytel, questa è la vostra occasione d'oro per riconciliarvi con Quruitzia! Si riconosce nella tragedia del cucciolo ed è visibilmente scossa...",
    382: "Ah! (bisbigliando) ...Capisco, è qui che devo accogliere e comprendere i sentimenti più sinceri di Quruitzia, dico bene? Ve ne sarò grato per sempre... milady Farris!",
    383: "...(le lancia un'occhiata d'intesa)",
    384: "Aha! Fingerti docile e indifeso non ti salverà dalla nostra collera, drago malefico! Abbiamo rischiato di sacrificare una compagna a causa tua: ora salderai i conti!",
    385: "Fermati, Loytel...!",
    386: "Uhm, hai già la memoria corta, Quruitzia? Questo rettile mostruoso voleva immolarti...",
    387: "Questo piccolino non ha fatto niente di male...!",
    388: "Piccolo drago, rispondimi... perché hai scelto proprio me come sacrificio?",
    389: "(...tuoi... occhi...)",
    390: "I miei... occhi? Che cosa intendi...?",
    391: "(...mokyuu...)",
    392: "Ma senti un po'! Si spaventa a tal punto da non riuscire nemmeno a balbettare?! Eh, faceva tanto il gradasso quando si nascondeva dietro quell'ombra immane!",
    393: "...Loytel, chiudi quella boccaccia!",
    395: "(ma... mma...)",
    396: "...Eh?!"
}

def apply():
    print(f"Loading {LOYTEL_FILE}...")
    wb = openpyxl.load_workbook(LOYTEL_FILE)
    ws = wb.active
    
    headers = {ws.cell(1, c).value: c for c in range(1, ws.max_column + 1)}
    col_text = headers.get('text', 12)
    
    updated = 0
    for r, it_text in LOYTEL_PART1.items():
        if r <= ws.max_row:
            ws.cell(r, col_text, it_text)
            updated += 1
            
    wb.save(LOYTEL_FILE)
    print(f"Aggiornate con successo {updated} righe in loytel.xlsx (Part 1)")

if __name__ == '__main__':
    apply()
